function Counter() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    // Fiber Update Queue'ya { action: 1, next: null } eklenir
    setCount(prev => prev + 1); 
  };

  return <button onClick={handleClick}>Artır: {count}</button>;
}`},{id:"step-render-phase",name:"2. Render Phase & Fiber Tree Diffing",phase:"Render Phase",badgeColor:"bg-cyan-500/20 text-cyan-300 border-cyan-500/40",description:"React, bileşen fonksiyonunu çağırır ve yeni bir Virtual DOM (WorkInProgress Fiber) ağacı üretir. Bu aşama tamamen asenkron, duraklatılabilir ve saf JavaScript tabanlıdır (Hiçbir DOM mutasyonu yapılmaz).",technicalDetails:["Current Fiber Ağacı ile WorkInProgress (WIP) Fiber Ağacı O(n) heuristik diffing ile karşılaştırılır.","Bileşenin JSX fonksiyonu çalıştırılır: ReactElement = Component(props).",'Değişen her düğüme özel "Flags" (Placement, Update, Deletion) bayrakları atanır.',"Concurrent Mode devredeyse, yüksek öncelikli bir kullanıcı girdisi gelirse bu aşama anında iptal edilip baştan başlatılabilir!"],fiberAction:"workInProgress = createWorkInProgress(current, pendingProps); beginWork(); completeWork();",codeSnippet:`// 2. ADIM: React bileşeni çağırır ve Virtual DOM üretir
// Bu aşamada GERÇEK DOM'A DOKUNULMAZ!
const nextChildren = Counter(props);

// React Reconciliation algoritması eski ve yeni Fiber'ı kıyaslar:
if (currentFiber.memoizedProps !== nextProps) {
  workInProgressFiber.flags |= Update; // 'Update' bayrağı işaretlenir
}`},{id:"step-commit-dom",name:"3. Commit Phase (DOM Mutasyonu)",phase:"Commit Phase",badgeColor:"bg-emerald-500/20 text-emerald-300 border-emerald-500/40",description:"Render aşamasında bayraklandırılan tüm değişiklikler tek bir senkronize ve atomik işlemle gerçek tarayıcı DOM'una uygulanır.",technicalDetails:["Tarayıcı DOM ağacına appendChild, removeChild, textContent veya node.setAttribute çağrıları yapılır.","Current Tree referansı yeni WorkInProgress Tree ile yer değiştirir (Double Buffering mekanizması).","Bileşenin ref.current referansları yeni gerçek DOM düğümlerine bağlanır."],fiberAction:"root.current = finishedWork; commitMutationEffects(finishedWork, root);",codeSnippet:`// 3. ADIM: Gerçek DOM güncellenir
// HTML DOM'u doğrudan mutate edilir:
domNode.textContent = "Artır: 1"; 
domNode.setAttribute("aria-valuenow", "1");

// React Fiber Root güncellenir (Double Buffering)
root.current = workInProgressRoot;`},{id:"step-layout-effects",name:"4. useLayoutEffect & Senkron DOM Ölçümü",phase:"Commit Phase",badgeColor:"bg-purple-500/20 text-purple-300 border-purple-500/40",description:"DOM güncellendi ancak tarayıcı henüz ekrana çizim (Paint) yapmadı. Senkron olarak çalışan useLayoutEffect burada devreye girer.",technicalDetails:["Bileşen getBoundingClientRect() gibi ölçüm fonksiyonlarıyla DOM elemanının gerçek piksel koordinatlarını alır.","Eğer burada yeni bir setState yapılırsa, tarayıcı çizim yapmadan önce anında yeni bir re-render planlanır (Böylece ekranda titreme/flicker olmaz).","Ağır işlemler buraya konulursa tarayıcı ekran çizimini geciktirir."],fiberAction:"commitLayoutEffects(finishedWork, root); // Senkron çalıştırma",codeSnippet:`// 4. ADIM: Paint öncesi senkron useLayoutEffect çalışır
